// Gentle-wake index — record JAH-GGN-SUNRISECLOCK-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"max_lux": 300, "sounds": 5, "price_usd": 80};
var value = (m.max_lux*m.sounds/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-SUNRISECLOCK-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-SUNRISECLOCK-000001|' + value.toFixed(2) + ' wake index');

